    pub fn noun_scored(&self, word: &str, definiteness: Definiteness, case: Case, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (definiteness, case, number,) {
            (Definiteness::Indefinite, Case::Nominative, Number::Singular,) => Some(0),
            (Definiteness::Indefinite, Case::Nominative, Number::Plural,) => Some(1),
            (Definiteness::Indefinite, Case::Genitive, Number::Singular,) => Some(2),
            (Definiteness::Indefinite, Case::Genitive, Number::Plural,) => Some(3),
            (Definiteness::Indefinite, Case::Dative, Number::Singular,) => Some(4),
            (Definiteness::Indefinite, Case::Dative, Number::Plural,) => Some(5),
            (Definiteness::Definite, Case::Nominative, Number::Singular,) => Some(6),
            (Definiteness::Definite, Case::Nominative, Number::Plural,) => Some(7),
            (Definiteness::Definite, Case::Genitive, Number::Singular,) => Some(8),
            (Definiteness::Definite, Case::Genitive, Number::Plural,) => Some(9),
            (Definiteness::Definite, Case::Dative, Number::Singular,) => Some(10),
            (Definiteness::Definite, Case::Dative, Number::Plural,) => Some(11),
            _ => None,
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A noun form. The best candidate; the word itself if nothing is known.
